css:
.fc__h { margin: 0 0 .7rem; font-family: var(--os-font-body); font-weight: 700; font-size: 1.15rem; line-height: 1.08; color: var(--os-color-heading); }
.fc__t { font-size: 1.125rem; line-height: 1.65; color: var(--os-color-heading); }
.fc__t p { margin: 0; min-height: 0 !important; }
.fc__t ul { list-style: none; padding: 0; margin: 0; }
.fc__t li { padding: .18rem 0; margin: 0; max-width: 62ch; }
.fc__t a { display: inline !important; min-height: 0 !important; min-width: 0 !important; padding: 0 !important; color: var(--os-color-heading); text-decoration: underline; text-underline-offset: .18em; text-decoration-thickness: .08em; }
.fc__t a:hover { text-decoration-thickness: .14em; }
.fc__t--s { font-size: .95rem; line-height: 1.65; color: var(--os-color-text-muted); margin: .95rem 0; }
